mapper.select:
SELECT datasource_id, datasource_name, database_name, table_name, check_item, CAST(check_time AS DATE) AS check_date, SUM(check_record_count) AS check_record_count, SUM(fail_record_count) AS fail_record_count FROM data_quality_check_result WHERE fail_record_count > 0
AND check_time >= #{startTime}
AND check_time < #{endTime}
AND datasource_id = #{datasourceId}
AND database_name = #{databaseName}
AND table_name LIKE CONCAT('%', #{tableName}, '%')
GROUP BY datasource_id, datasource_name, database_name, table_name, check_item, CAST(check_time AS DATE) ORDER BY check_date DESC, table_name ASC, check_item ASC
